from pathlib import Path
R=Path(__file__).resolve().parent.parent
out=['# -*- coding: utf-8 -*-']
for profile,mz,lead,se in [('zero',0,False,0),('one',1,False,2),('trust',2,True,2),('no_lead',2,False,0)]:
 name='cs_dinner_revised_'+profile;branch='c' if mz==0 else 'b' if mz==1 else 'a'
 scores=(mz,1,1,se,2,2)
 out+=['testcase '+name+':','    pause 1.0','    $ renpy.set_physical_size((1280,720))','    $ _preferences.text_cps = 0','    $ _test.force = True','    $ _test.timeout = 50.0','    run Start("cs_qa_dinner_revised_load")','    pause 0.5','    $ cs_friend_mz,cs_friend_sl,cs_friend_mi,cs_friend_se,cs_friend_viola,cs_friend_un = '+repr(scores),'    $ cs_qa_part09_scores = '+repr(scores),'    $ cs_qa_part09_visits = []','    $ cs_mz_map_lead = '+str(lead),'    $ cs_sl_good_seats = False','    $ cs_mi_intro_revised = False','    $ cs_qa_global_audit = True','    $ cs_qa_part09_audit = True','    run Jump("cs_qa_dinner_revised_run")','    click until label cs_check_dinner64_greeting','    pause 0.5','    assert renpy.showing("cs_zhenya") and renpy.showing("cs_darya")','    assert not renpy.showing("cs_semen")','    $ cs_qa_capture("'+name+'_greeting")','    click until label cs_check_dinner64'+branch,'    pause 0.5','    assert renpy.showing("cs_zhenya") and renpy.showing("cs_darya")']
 if mz==0:out+=['    click until label cs_check_dinner64_separate','    pause 0.5','    assert not renpy.showing("cs_zhenya") and renpy.showing("cs_darya")','    $ cs_qa_capture("'+name+'_alone")']
 else:
  out+=['    click until label cs_check_dinner64d','    pause 0.5','    assert renpy.showing("cs_zhenya") and renpy.showing("cs_darya")','    $ cs_qa_capture("'+name+'_shared")']
  if lead or mz==1:out+=['    click until label cs_check_dinner64'+('d1' if lead else 'd2'),'    pause 0.5','    $ cs_qa_capture("'+name+'_trust")','    $ renpy.take_screenshot()','    $ renpy.save("'+name+'-trust")','    $ cs_mz_map_lead = not cs_mz_map_lead','    $ renpy.load("'+name+'-trust")','    pause 0.5','    assert cs_mz_map_lead == '+str(lead)]
 out+=['    click until label cs_check_part09_semen','    pause 0.5','    assert renpy.showing("cs_semen") and renpy.showing("cs_darya")','    assert bool(renpy.showing("cs_zhenya")) == '+str(mz>=1),'    $ cs_qa_capture("'+name+'_semen")','    click until label cs_check_part09_semen_left','    pause 0.5','    assert not renpy.showing("cs_semen")','    assert bool(renpy.showing("cs_zhenya")) == '+str(mz>=1)]
 if mz>=1:out+=['    click until label cs_check_dinner64_zhenya_left','    pause 0.5','    assert not renpy.showing("cs_zhenya") and not renpy.showing("cs_semen")']
 out+=['    click until label cs_check_dinner64_exit','    pause 0.5','    assert renpy.showing("bg ext_square_sunset") and renpy.showing("cs_darya")','    assert not renpy.showing("cs_zhenya") and not renpy.showing("cs_semen")','    $ cs_qa_capture("'+name+'_exit")','    click until label cs_check_part09_pending','    pause 3.0','    assert cs_lena_elbow_bandaged and cs_lena_no_sport_day2','    assert cs_mz_map_lead == '+str(lead),'    assert cs_sl_good_seats and cs_mi_intro_revised','    assert not cs_day02_done','    assert cs_qa_part09_visits.count("cs_day02_64") == 1 and cs_qa_part09_visits.count("cs_day02_65") == 1','    assert ("cs_day02_64d1" in cs_qa_part09_visits) == '+str(lead),'    assert ("cs_day02_64d2" in cs_qa_part09_visits) == '+str(mz==1),'    assert ("cs_day02_64d" in cs_qa_part09_visits) == '+str(mz>=1),'    assert __import__("__builtin__").all(("cs_day02_64"+x in cs_qa_part09_visits) == (x=="'+branch+'") for x in ("a","b","c"))','    assert (cs_friend_mz,cs_friend_sl,cs_friend_mi,cs_friend_se,cs_friend_viola,cs_friend_un) == cs_qa_part09_scores','    $ cs_qa_capture("'+name+'_end")','    $ renpy.take_screenshot()','    $ renpy.save("'+name+'-end")','    $ cs_mz_map_lead = not cs_mz_map_lead','    $ renpy.load("'+name+'-end")','    pause 0.5','    assert cs_mz_map_lead == '+str(lead),'    $ open(config.gamedir + "/mods/chuzaya_smena/qa/'+name+'_pass.txt", "w").write("PASS")','    run Quit(confirm=False)','']
(R/'qa/dinner_revised_routes_test.rpy').write_text('\n'.join(out),encoding='utf8')
print('Four replacement-dinner profiles generated')
